#!/usr/bin/env python3
"""Fill project proposal HWPX template placeholders from JSON.

Outputs: /root/project_proposal_ready.hwpx

Contract highlights:
- Replace {{key}} placeholders using /root/project_proposal.json.
- Normalize budget values like ₩450,000,000 -> ₩450000000 (remove commas, keep symbol).
- For phase lines (단계1/2/3), parse the date range present in the replaced text and append " (N개월)".
- If a paragraph (<hp:p>) is modified, remove layout-cache elements inside it (e.g., hp:lineSegArray / hp:linesegarray / hp:lineseg*).
- Verify no {{...}} placeholders remain.
"""

from __future__ import annotations

import json
import re
import sys
import zipfile
from dataclasses import dataclass
from io import BytesIO
from typing import Dict, Iterable, List, Optional, Tuple

import xml.etree.ElementTree as ET


TEMPLATE_PATH = "/root/project_proposal_template.hwpx"
JSON_PATH = "/root/project_proposal.json"
OUT_PATH = "/root/project_proposal_ready.hwpx"


PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")


def flatten_dict(d: dict, prefix: str = "") -> Dict[str, str]:
    out: Dict[str, str] = {}
    for k, v in d.items():
        key = f"{prefix}.{k}" if prefix else str(k)
        if isinstance(v, dict):
            out.update(flatten_dict(v, prefix=key))
        else:
            out[key] = "" if v is None else str(v)
    return out


_CURRENCY_SYMBOLS = ("₩", "$", "€", "¥", "£")


def normalize_budget(val: str) -> str:
    # Only remove thousands-separating commas when a currency symbol is present.
    if "," in val and any(sym in val for sym in _CURRENCY_SYMBOLS):
        return val.replace(",", "")
    return val


def replace_placeholders(text: str, mapping: Dict[str, str]) -> Tuple[str, List[str]]:
    missing: List[str] = []

    def repl(m: re.Match) -> str:
        raw_key = m.group(1)
        key = raw_key.strip()
        if key in mapping:
            return normalize_budget(mapping[key])
        missing.append(key)
        return m.group(0)

    return PLACEHOLDER_RE.sub(repl, text), missing


_RANGE_RE = re.compile(
    r"(?P<sy>\d{4})[.\-](?P<sm>\d{2})(?:[.\-]\d{2})?\s*~\s*(?P<ey>\d{4})[.\-](?P<em>\d{2})(?:[.\-]\d{2})?"
)
_SINGLE_MONTH_RE = re.compile(r"(?P<y>\d{4})[.\-](?P<m>\d{2})(?![.\-]\d{2})")


def month_span_from_text(text: str) -> Optional[int]:
    """Parse a month span from an already-present date range inside text.

    Examples:
      "(2026-08 ~ 2026-10)" -> 3
      "(2027-01)" -> 1
    """
    m = _RANGE_RE.search(text)
    if m:
        sy = int(m.group("sy"))
        sm = int(m.group("sm"))
        ey = int(m.group("ey"))
        em = int(m.group("em"))
        return (ey - sy) * 12 + (em - sm) + 1

    # If there is no explicit range, but there is a single YYYY-MM / YYYY.MM, treat as 1 month.
    # Avoid picking up the first of multiple months; if multiple months exist without ~, we skip.
    months = list(_SINGLE_MONTH_RE.finditer(text))
    if len(months) == 1:
        return 1

    return None


def iter_text_elems_in_para(p: ET.Element, ns: Dict[str, str]) -> List[ET.Element]:
    return list(p.findall(".//hp:t", ns))


def combined_para_text(p: ET.Element, ns: Dict[str, str]) -> str:
    parts: List[str] = []
    for t in iter_text_elems_in_para(p, ns):
        parts.append(t.text or "")
    return "".join(parts)


def set_para_text(p: ET.Element, ns: Dict[str, str], new_text: str) -> None:
    ts = iter_text_elems_in_para(p, ns)
    if not ts:
        return
    ts[0].text = new_text
    for t in ts[1:]:
        t.text = ""


def strip_layout_cache_in_para(p: ET.Element) -> None:
    """Remove layout-cache-ish elements inside a modified paragraph.

    The provided templates use <hp:linesegarray />, but real docs may also use lineSegArray, lineSeg, etc.
    We'll remove any descendant whose localname contains 'lineseg' (case-insensitive).
    """

    def localname(tag: str) -> str:
        if tag.startswith("{"):
            return tag.split("}", 1)[1]
        return tag

    # ElementTree doesn't provide parent pointers; remove by walking parents.
    # We do a post-order traversal: for each parent, filter its children.
    for parent in list(p.iter()):
        # list() because we'll mutate children
        for child in list(parent):
            ln = localname(child.tag).lower()
            if "lineseg" in ln:  # matches linesegarray, lineSegArray, lineseg, ...
                parent.remove(child)


@dataclass
class XmlProcessResult:
    xml_bytes: bytes
    missing_keys: List[str]
    modified: bool


def process_section_xml(xml_bytes: bytes, mapping: Dict[str, str], filename: str) -> XmlProcessResult:
    text = xml_bytes.decode("utf-8")
    root = ET.fromstring(text)

    # Namespace discovery
    ns_uri = root.tag[root.tag.find("{") + 1 : root.tag.find("}")] if root.tag.startswith("{") else ""
    ns = {"hp": ns_uri} if ns_uri else {}
    if ns_uri:
        ET.register_namespace("hp", ns_uri)

    missing_all: List[str] = []
    modified_any = False

    # Track which paragraphs contain phase placeholders before replacement.
    phase_keys = ("단계1", "단계2", "단계3")

    for p in root.findall(".//hp:p", ns) if ns else root.findall(".//p"):
        original = combined_para_text(p, ns)
        if not original:
            continue

        new_text, missing = replace_placeholders(original, mapping)
        missing_all.extend(missing)

        modified = (new_text != original)

        # Month span append for phase lines (based on which phase placeholder was present in the ORIGINAL text).
        # We still compute span from the replaced text, per task requirement.
        if any(f"{{{{{k}}}}}" in original for k in phase_keys):
            span = month_span_from_text(new_text)
            if span is not None and f"({span}개월)" not in new_text:
                new_text = new_text + f" ({span}개월)"
                modified = True

        if modified:
            set_para_text(p, ns, new_text)
            strip_layout_cache_in_para(p)
            modified_any = True

    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return XmlProcessResult(xml_bytes=out_bytes, missing_keys=missing_all, modified=modified_any)


def has_placeholders(data: bytes) -> bool:
    return bool(PLACEHOLDER_RE.search(data.decode("utf-8", errors="ignore")))


def main() -> int:
    with open(JSON_PATH, "r", encoding="utf-8") as f:
        data = json.load(f)
    mapping = flatten_dict(data)

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin:
        infos = zin.infolist()

        # Preserve ordering; if a mimetype file exists, force it first and stored.
        names = [zi.filename for zi in infos]
        if "mimetype" in names:
            infos = [next(zi for zi in infos if zi.filename == "mimetype")] + [
                zi for zi in infos if zi.filename != "mimetype"
            ]

        out_buf = BytesIO()
        with zipfile.ZipFile(out_buf, "w") as zout:
            missing_keys_by_file: Dict[str, List[str]] = {}
            modified_files: List[str] = []

            for zi in infos:
                raw = zin.read(zi.filename)
                new_raw = raw

                if zi.filename.lower().endswith(".xml"):
                    res = process_section_xml(raw, mapping, zi.filename)
                    new_raw = res.xml_bytes
                    if res.modified:
                        modified_files.append(zi.filename)
                    if res.missing_keys:
                        missing_keys_by_file.setdefault(zi.filename, []).extend(res.missing_keys)

                out_zi = zipfile.ZipInfo(filename=zi.filename, date_time=zi.date_time)
                out_zi.compress_type = zi.compress_type
                out_zi.comment = zi.comment
                out_zi.extra = zi.extra
                out_zi.internal_attr = zi.internal_attr
                out_zi.external_attr = zi.external_attr
                out_zi.create_system = zi.create_system
                out_zi.create_version = zi.create_version
                out_zi.extract_version = zi.extract_version
                out_zi.flag_bits = zi.flag_bits

                if zi.filename == "mimetype":
                    out_zi.compress_type = zipfile.ZIP_STORED

                zout.writestr(out_zi, new_raw)

        out_bytes = out_buf.getvalue()

    # Verify placeholders are gone (scan the whole output zip).
    with zipfile.ZipFile(BytesIO(out_bytes), "r") as zchk:
        remaining: Dict[str, List[str]] = {}
        for name in zchk.namelist():
            if name.lower().endswith(".xml"):
                content = zchk.read(name)
                hits = sorted(set(m.group(0) for m in PLACEHOLDER_RE.finditer(content.decode("utf-8", errors="ignore"))))
                if hits:
                    remaining[name] = hits

    if remaining:
        for fn, hits in remaining.items():
            print(f"ERROR: Remaining placeholders in {fn}: {hits}", file=sys.stderr)
        return 2

    # Warn/error on missing keys (but by this point placeholders should be gone).
    if any(missing_keys_by_file.values()):
        # In case a placeholder was replaced in a weird way, still surface this.
        for fn, keys in missing_keys_by_file.items():
            uniq = sorted(set(keys))
            print(f"WARNING: Missing keys while processing {fn}: {uniq}", file=sys.stderr)

    with open(OUT_PATH, "wb") as f:
        f.write(out_bytes)

    print(f"Wrote: {OUT_PATH}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

